# 두 수를 비교하는 프로그램
n1, n2 = map(int, input().split())
if n1 > n2:
  print("%d(이)가 %d보다 큼." %(n1, n2))
elif n1 == n2:
  print("두 수가 같음.")
else :
  print("%d(이)가 %d보다 큼." %(n2, n1))

