a = int(input())
if 1 <= a < 10:
  print("한자릿수 입니다.")
elif 10 <= a < 100 :
  print("두자릿수 입니다.")
elif 100 <= a < 1000 :
  print("세자릿수 입니다.")
else:
  print("범위를 벗어났습니다.")

a, b, c = map(int, input().split())
